};
const $=id=>document.getElementById(id);
let state=null, selectedClass='warrior', pending=null, enemy=null;
const statNames={str:'근력',dex:'민첩',wis:'지혜',cha:'매력'};
function freshState(name,role){const c=classes[role];return {name,role,hp:c.hp,maxHp:c.hp,mp:c.mp,maxMp:c.mp,stats:{...c.stats},items:[...c.items],scene:'edge',visits:0,log:[],combat:null};}
function save(){if(state)localStorage.setItem('ashmoon-save',JSON.stringify(state));}
function addLog(text){state.log.unshift({text,time:new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})});state.log=state.log.slice(0,12);renderLog();save();}
function showToast(text){const t=$('toast');t.textContent=text;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),1800);}
function statMod(key){return state.stats[key]||0;}
function applyEffects(e={}){if(e.heal)state.hp=Math.min(state.maxHp,state.hp+e.heal);if(e.mp)state.mp=Math.max(0,Math.min(state.maxMp,state.mp+e.mp));if(e.item&&!state.items.includes(e.item)){state.items.push(e.item);showToast(`${e.item} 획득`)}updateSheet();}
function updateSheet(){if(!state)return;$('charName').textContent=state.name;$('charRole').textContent=classes[state.role].name;$('portraitIcon').textContent=classes[state.role].icon;$('hpText').textContent=`${state.hp} / ${state.maxHp}`;$('mpText').textContent=`${state.mp} / ${state.maxMp}`;$('hpBar').style.width=`${Math.max(0,state.hp/state.maxHp*100)}%`;$('mpBar').style.width=`${Math.max(0,state.mp/state.maxMp*100)}%`;for(const key of Object.keys(statNames))$(key+'Stat').textContent=(statMod(key)>=0?'+':'')+statMod(key);$('inventory').innerHTML=state.items.map((item,i)=>`<button class="item" data-item="${i}" title="물약은 전투 중 사용할 수 있습니다">${item}</button>`).join('');}
function renderLog(){$('logList').innerHTML=state.log.length?state.log.map(e=>`<div class="log-entry"><time>${e.time}</time>${e.text}</div>`).join(''):'<div class="log-entry">아직 발자국이 없습니다.</div>';}
function render(){if(!state)return;const s=scenes[state.scene];if(!s)return;pending=null;$('resultBox').classList.remove('show');$('chapterTag').textContent=state.scene.startsWith('ending')?'EPILOGUE · 03':state.scene==='edge'?'PROLOGUE · 01':state.scene==='ruin'||state.scene==='gate'?'CHAPTER II · 02':'CHAPTER I · 01';$('sceneTitle').textContent=s.title;$('sceneKicker').textContent=s.kicker;$('sceneCounter').textContent=s.time;$('storyText').innerHTML=s.text||'';$('choiceHeading').style.display=s.ending?'none':'flex';$('choices').innerHTML='';$('progress').innerHTML=[0,1,2,3,4].map((n)=>`<i class="${Math.min(state.visits,4)>=n?'active':''}"></i>`).join('');$('sceneCard').querySelector('.scene-art').style.background=s.boss?'linear-gradient(0deg,#121811 0%,#121811cc 18%,transparent 76%),radial-gradient(ellipse at 68% 34%,#b14b3544,transparent 36%),linear-gradient(130deg,#392b27,#554036 44%,#28221f 67%,#151b17)':'';
if(s.ending){$('choices').innerHTML=`<div class="ending"><div class="sigil">${s.good?'☾':'✦'}</div><h2>${s.good?'빛은 다시 길이 되고':'그림자는 약속을 기억한다'}</h2><p>${s.good?'당신의 여정은 전설이 되었습니다.':'모든 모험이 밝은 곳에 닿는 것은 아닙니다.'}<br>함께 걸어준 모험가, ${state.name}에게.</p><button class="restart" id="restartButton">새로운 모험 시작하기</button></div>`;$('restartButton').onclick=()=>{localStorage.removeItem('ashmoon-save');state=null;$('setupOverlay').style.display='grid';};$('diceCaption').textContent='모험 완료';$('diceNumber').textContent='✦';return;}
if(s.combat){if(!state.combat||state.combat.scene!==state.scene){state.combat={scene:state.scene,hp:s.boss?22:12,max:s.boss?22:12};addLog(s.boss?'종탑의 수호자가 깨어났다.':'그림자 짐승이 길을 막아선다.');}renderCombat(s);}
else{$('choices').innerHTML=s.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><span><span class="choice-label">${c.label}</span><span class="choice-meta">${c.meta||'이야기를 이어간다'}</span></span><span class="choice-arrow">›</span></button>`).join('');document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(s.choices[+b.dataset.choice]));$('diceCaption').textContent='선택에 따라 굴림';$('diceNumber').textContent='—';}
updateSheet();save();}

