updateSheet();save();}
function renderCombat(s){const c=state.combat;const enemyName=s.boss?'종탑의 수호자':'그림자 짐승';$('storyText').innerHTML=s.boss?'문이 열리며, 달빛을 삼킨 갑옷의 수호자가 깨어난다. 가슴 한가운데 박힌 잿빛 수정이 맥동한다. <em>“돌아가라, 필멸자.”</em>':'그림자에서 짐승 하나가 튀어나온다. 갈라진 입 사이로 푸른 불꽃이 새어 나오고, 날카로운 발톱이 눈을 긁는다.';$('choices').innerHTML=`<div class="combat-top"><span>⚔ ${enemyName}</span><span>${c.hp} / ${c.max} HP</span></div><div class="enemy-bar"><i style="width:${Math.max(0,c.hp/c.max*100)}%"></i></div><button class="choice" data-combat="strike"><span><span class="choice-label">무기를 휘둘러 공격한다</span><span class="choice-meta">근력 판정 · 난이도 ${s.boss?13:10}</span></span><span class="choice-arrow">›</span></button><button class="choice" data-combat="magic" ${state.mp<2?'disabled':''}><span><span class="choice-label">달빛 마법을 쏘아 보낸다</span><span class="choice-meta">정신력 2 소모 · 지혜 판정</span></span><span class="choice-arrow">✧</span></button><button class="choice" data-combat="guard"><span><span class="choice-label">자세를 낮추고 반격을 노린다</span><span class="choice-meta">민첩 판정 · 성공 시 피해 없음</span></span><span class="choice-arrow">◈</span></button><button class="choice" data-combat="potion" ${!state.items.some(x=>x.includes('물약'))?'disabled':''}><span><span class="choice-label">치유 물약을 마신다</span><span class="choice-meta">생명력 8 회복 · 소지한 물약 1개 사용</span></span><span class="choice-arrow">＋</span></button>`;document.querySelectorAll('[data-combat]').forEach(b=>b.onclick=()=>combatAction(b.dataset.combat,s));$('diceCaption').textContent='전투 중';$('diceNumber').textContent='⚔';}
function combatAction(action,s){const c=state.combat;let roll=Math.ceil(Math.random()*20),mod=0,total=roll,dc=s.boss?13:10,success=false,msg='',enemyHit=0;let stat='str';if(action==='strike'){mod=statMod('str');total+=mod;success=total>=dc;const damage=success?Math.max(3,roll===20?9:5+mod):0;c.hp-=damage;msg=success?`${damage}의 피해를 입혔다.`:'공격이 빗나갔다.';}
else if(action==='magic'){state.mp-=2;stat='wis';mod=statMod('wis');total+=mod;success=total>=dc-1;const damage=success?Math.max(4,roll===20?11:6+mod):0;c.hp-=damage;msg=success?`달빛이 폭발하며 ${damage}의 피해를 입혔다.`:'마법이 갑옷에 튕겨 나갔다.';}
else if(action==='guard'){stat='dex';mod=statMod('dex');total+=mod;success=total>=11;msg=success?'공격을 흘려내고 빈틈을 잡았다.':'몸을 웅크렸지만 발톱이 스쳤다.';}
else if(action==='potion'){let i=state.items.findIndex(x=>x.includes('물약'));if(i<0)return;const item=state.items.splice(i,1)[0];const healed=Math.min(8,state.maxHp-state.hp);state.hp+=healed;msg=`${item}을(를) 마셔 생명력 ${healed} 회복.`;roll=null;}
if(c.hp>0&&action!=='guard'){enemyHit=2+Math.floor(Math.random()*3);state.hp-=enemyHit;msg+=` 적의 반격으로 ${enemyHit} 피해.`;}else if(c.hp>0&&action==='guard'&&!success){enemyHit=2;state.hp-=enemyHit;msg+=` ${enemyHit} 피해.`;}
if(c.hp<=0){c.hp=0;pending={to:s.boss?'ending_good':'ruin',text:`${s.boss?'수호자':'그림자 짐승'}이 쓰러졌다. ${s.boss?'수정이 깨지고, 달빛이 종탑을 채운다.':'길을 막던 그림자가 흩어졌다.'}`};}
