async function(page) {
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.evaluate(() => { Math.random = () => 0.99; });
  await page.getByRole('button', { name: /모험을 시작한다/ }).click();
  await page.locator('#choices .choice').first().click();
  await page.locator('#continueButton').click();
  await page.locator('#choices .choice').first().click();
  await page.locator('#continueButton').click();
  await page.locator('#choices .choice').first().click();
  await page.locator('#continueButton').click();
  for (let i = 0; i < 5 && !(await page.locator('.ending').count()); i++) {
    if (await page.locator('[data-combat="strike"]').count()) {
      await page.locator('[data-combat="strike"]').click();
      await page.locator('#continueButton').click();
    } else if (await page.locator('#choices .choice').count()) {
      await page.locator('#choices .choice').first().click();
      await page.locator('#continueButton').click();
    }
  }
  return await page.locator('#sceneTitle').innerText();
}

